const V=require('./vertebrates'),Q=require('./aquatic'),assert=require('node:assert/strict'),fs=require('fs');let checks=[];function ck(n,v){assert.ok(v,n);checks.push(n)}
function balance(s){ck('balanço C/N/P/água',Object.values(s.last).every(x=>Number.isFinite(x)&&Math.abs(x)<1e-6))}
let s=Q.create(),idx=V.index(s),a=s.animals[0],old=a.pos,dest=(old+1)%s.cells.length;idx.move(a,dest);ck('índice acompanha movimento',!idx.A.get(old).has(a)&&idx.A.get(dest).has(a));ck('consulta por ID',idx.byId.get(a.id)===a);let [f,g]=s.animals.filter(x=>x.sp===3);g.sex=f.sex;idx.move(g,f.pos);ck('competição territorial mesmo sexo',V.territory(s,f,f.pos,idx)<1);g.sex=f.sex==='F'?'M':'F';ck('não bloqueia parceiro reprodutivo',V.territory(s,f,f.pos,idx)===1);
let t=Q.create();let ten=t.animals.find(a=>a.sp===4),c=t.cells[ten.pos];c.water=c.cap*.35;c.surface=0;c.litter=.6;ck('abrigo seco adequado',V.shelter(t,ten,ten.pos)>.06);c.surface=9;ck('abrigo alagado rejeitado',V.shelter(t,ten,ten.pos)===0);c.surface=0;t.step=180*4;t.day=180;t.weather='drought';Q.tick(t);ck('torpor sazonal reduz atividade',ten.state==='torpor'&&t.behaviorEvents.torpor>0);balance(t);
let z=Q.create();let m=z.animals.find(a=>a.sp===4);z.animals=[m];z.insects=[];let site=z.cells.findIndex(c=>c.sp===6&&!c.channel);m.pos=site;m.c=.024;m.water=1;let fruit=z.cells[site];fruit.fruit=.08;fruit.fruitN=.0064;fruit.phase='fruto';fruit.phaseDay=0;Q.tick(z);ck('tenreque consome fruto alternativo',z.behaviorEvents.fruitFallback===1&&z.animalEvents.food.fruit>0);balance(z);
let q=Q.create();for(let i=0;i<120;i++){Q.tick(q);assert.ok(Object.values(q.last).every(x=>Number.isFinite(x)&&Math.abs(x)<1e-6))}ck('busca espacial em simulação',q.behaviorEvents.localQueries>0);ck('repouso em abrigos durante ciclo',q.behaviorEvents.shelterRest>0);fs.writeFileSync('behavior-results.json',JSON.stringify({checks,events:q.behaviorEvents,pop:V.metrics(q)},null,2));console.log(checks,q.behaviorEvents,V.metrics(q))
